@Override
@Transactional(rollbackOn = {Exception.class})
public void validate(Inventory inventory) throws AxelorException {
  if (inventory.getStatusSelect() == null
      || inventory.getStatusSelect() != InventoryRepository.STATUS_COMPLETED) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(StockExceptionMessage.INVENTORY_VALIDATE_WRONG_STATUS));
  }

  checkMissingStockLocation(inventory);
  inventory.setValidatedOn(
      appBaseService.getTodayDateTime(inventory.getCompany()).toLocalDateTime());
  inventory.setStatusSelect(InventoryRepository.STATUS_VALIDATED);
  inventory.setIsStockMoveBlocked(false);
  inventory.setValidatedBy(AuthUtils.getUser());

  generateStockMoves(inventory, true);
  generateStockMoves(inventory, false);

  inventoryStockLocationUpdateService.storeLastInventoryData(inventory);
}

public void generateStockMoves(Inventory inventory, boolean isEnteringStock)
    throws AxelorException {

  final Long inventoryId = inventory.getId();

  Company company = inventory.getCompany();
  StockConfig stockConfig = stockConfigService.getStockConfig(company);
  StockLocation virtualInventoryLocation =
      stockConfigService.getInventoryVirtualStockLocation(stockConfig);

  Map<StockMoveLocationKey, Long> stockMoveIdMap = new HashMap<>();

  final Inventory[] inventoryHolder = {inventoryRepo.find(inventoryId)};
  final StockLocation[] virtualInvLocHolder = {
    virtualInventoryLocation != null
        ? stockLocationRepository.find(virtualInventoryLocation.getId())
        : null
  };

  Query<InventoryLine> query =
      inventoryLineRepository
          .all()
          .filter(
              "self.inventory.id = :inventoryId and self.stockLocation is not null and self.id > :lastSeenId")
          .bind("inventoryId", inventoryId)
          .order("id");

  BatchProcessorHelper.builder()
      .build()
      .<InventoryLine, AxelorException>forEachByQuery(
          query,
          inventoryLine -> {
            if (computeDiff(inventoryLine, isEnteringStock).signum() <= 0) {
              return;
            }
            StockLocation realStockLocation = inventoryLine.getStockLocation();
            StockLocation fromStockLocation =
                isEnteringStock ? virtualInvLocHolder[0] : realStockLocation;
            StockLocation toStockLocation =
                isEnteringStock ? realStockLocation : virtualInvLocHolder[0];

            StockMoveLocationKey key =
                new StockMoveLocationKey(fromStockLocation.getId(), toStockLocation.getId());
            Long stockMoveId = stockMoveIdMap.get(key);
            StockMove stockMove;
            if (stockMoveId == null) {
              stockMove =
                  generateStockMove(
                      inventoryHolder[0], isEnteringStock, fromStockLocation, toStockLocation);
              stockMoveIdMap.put(key, stockMove.getId());
            } else {
              stockMove = getStockMove(stockMoveId);
            }

            generateStockMoveLines(
                stockMove,
                fromStockLocation,
                toStockLocation,
                List.of(inventoryLine),
                isEnteringStock);
          },
          () -> {
            inventoryHolder[0] = inventoryRepo.find(inventoryId);
            virtualInvLocHolder[0] =
                Optional.ofNullable(virtualInventoryLocation)
                    .map(StockLocation::getId)
                    .map(stockLocationRepository::find)
                    .orElse(null);
          });

  realizeGeneratedStockMoves(stockMoveIdMap);
}

public StockMove generateStockMove(
    Inventory inventory,
    boolean isEnteringStock,
    StockLocation fromStockLocation,
    StockLocation toStockLocation)
    throws AxelorException {

  Company company = inventory.getCompany();
  String inventorySeq = inventory.getInventorySeq();

  LocalDate inventoryDate = inventory.getPlannedStartDateT().toLocalDate();
  LocalDate realDate = inventory.getValidatedOn().toLocalDate();
  StockMove stockMove =
      stockMoveService.createStockMove(
          null,
          null,
          company,
          fromStockLocation,
          toStockLocation,
          realDate,
          inventoryDate,
          null,
          StockMoveRepository.TYPE_INTERNAL);

  stockMove.setName(inventorySeq);

  stockMove.setInventory(inventory);
  stockMove.setOrigin(inventorySeq);

  return stockMoveRepo.save(stockMove);
}

protected void realizeGeneratedStockMoves(Map<StockMoveLocationKey, Long> stockMoveIdMap)
    throws AxelorException {
  if (ObjectUtils.isEmpty(stockMoveIdMap)) {
    return;
  }
  List<Long> ids =
      stockMoveIdMap.values().stream()
          .filter(Objects::nonNull)
          .distinct()
          .collect(Collectors.toList());
  if (CollectionUtils.isEmpty(ids)) {
    return;
  }
  for (Long id : ids) {
    StockMove stockMove = getStockMove(id);
    stockMoveRealize(stockMove);
  }
}

protected void stockMoveRealize(StockMove stockMove) throws AxelorException {
  long stockMoveLinesCount = getStockMoveLinesCount(stockMove);
  if (stockMoveLinesCount == 0l) {
    return;
  }
  stockMoveService.plan(getStockMove(stockMove));
  stockMoveService.copyQtyToRealQty(getStockMove(stockMove));
  stockMoveService.realize(getStockMove(stockMove), false);
}

protected void generateStockMoveLines(
    StockMove stockMove,
    StockLocation fromStockLocation,
    StockLocation toStockLocation,
    List<InventoryLine> inventoryLineList,
    boolean isEnteringStock)
    throws AxelorException {
  for (InventoryLine inventoryLine : inventoryLineList) {
    generateStockMoveLines(
        inventoryLine, stockMove, isEnteringStock, fromStockLocation, toStockLocation);
  }
}

protected void generateStockMoveLines(
    InventoryLine inventoryLine,
    StockMove stockMove,
    boolean isEnteringStock,
    StockLocation fromStockLocation,
    StockLocation toStockLocation)
    throws AxelorException {
  Product product = inventoryLine.getProduct();
  TrackingNumber trackingNumber = inventoryLine.getTrackingNumber();
  BigDecimal diff = computeDiff(inventoryLine, isEnteringStock);
  if (diff.signum() <= 0) {
    return;
  }

  StockLocationLine stockLocationLine =
      stockLocationLineFetchService.getStockLocationLine(toStockLocation, product);
  BigDecimal unitPrice = getAvgPrice(stockLocationLine);
  if (!inventoryLineService.isPresentInStockLocation(inventoryLine)) {
    unitPrice = inventoryLine.getPrice();
  }

  StockMoveLine stockMoveLine =
      stockMoveLineService.createStockMoveLine(
          product,
          product.getName(),
          product.getDescription(),
          diff,
          unitPrice,
          unitPrice,
          product.getUnit(),
          stockMove,
          StockMoveLineService.TYPE_NULL,
          false,
          BigDecimal.ZERO,
          fromStockLocation,
          toStockLocation);
  if (stockMoveLine == null) {
    throw new AxelorException(
        inventoryLine.getInventory(),
        TraceBackRepository.CATEGORY_CONFIGURATION_ERROR,
        I18n.get(StockExceptionMessage.INVENTORY_7)
            + " "
            + inventoryLine.getInventory().getInventorySeq());
  }
  if (trackingNumber != null && stockMoveLine.getTrackingNumber() == null) {
    stockMoveLine.setTrackingNumber(trackingNumber);
  }
  stockMoveLineRepo.save(stockMoveLine);
}

protected BigDecimal computeDiff(InventoryLine inventoryLine, boolean isEnteringStock) {
  BigDecimal diff = inventoryLine.getRealQty().subtract(inventoryLine.getCurrentQty());
  if (!isEnteringStock) {
    diff = diff.negate();
  }
  return diff;
}

protected void checkMissingStockLocation(Inventory inventory) throws AxelorException {

  List<InventoryLine> inventoryLinesWithMissingStockLocation =
      inventoryLineRepository
          .all()
          .filter("self.inventory = :inventory and self.stockLocation is null")
          .bind("inventory", inventory)
          .fetch(
              INVENTORY_LINE_WITHOUT_STOCK_LOCATION_DISPLAY_LIMIT
                  + 1); // Fetch limit + 1 to check for excess items

  if (CollectionUtils.isEmpty(inventoryLinesWithMissingStockLocation)) {
    return;
  }

  StringHtmlListBuilder stringHTMLListInventoryLine = new StringHtmlListBuilder();
  inventoryLinesWithMissingStockLocation.stream()
      .forEach(
          inventoryLine -> {
            if (inventoryLine.getTrackingNumber() == null) {
              stringHTMLListInventoryLine.append(inventoryLine.getProduct().getFullName());
            } else {
              stringHTMLListInventoryLine.append(
                  String.format(
                      "%s : %s",
                      inventoryLine.getProduct().getFullName(),
                      inventoryLine.getTrackingNumber().getTrackingNumberSeq()));
            }
          });

  if (inventoryLinesWithMissingStockLocation.size()
      > INVENTORY_LINE_WITHOUT_STOCK_LOCATION_DISPLAY_LIMIT) {
    stringHTMLListInventoryLine.append("...");
  }

  throw new AxelorException(
      TraceBackRepository.CATEGORY_NO_VALUE,
      String.format(
          I18n.get(StockExceptionMessage.INVENTORY_LINE_STOCK_LOCATION_MISSING),
          stringHTMLListInventoryLine));
}

protected long getStockMoveLinesCount(StockMove stockMove) {
  return stockMoveLineRepo
      .all()
      .filter("self.stockMove.id = :stockMoveId")
      .bind("stockMoveId", stockMove.getId())
      .count();
}

@Override
public String realize(StockMove stockMove) throws AxelorException {
  return realize(stockMove, true);
}

@Override
public String realize(StockMove stockMove, boolean checkOngoingInventoryFlag)
    throws AxelorException {
  String newStockSeq = realizeStockMove(stockMove, checkOngoingInventoryFlag);

  if (stockMove.getTypeSelect() == StockMoveRepository.TYPE_OUTGOING
      && stockMove.getRealStockMoveAutomaticMail() != null
      && stockMove.getRealStockMoveAutomaticMail()) {
    sendMailForStockMove(stockMove, stockMove.getRealStockMoveMessageTemplate());
  }

  return newStockSeq;
}

@Transactional(rollbackOn = {Exception.class})
protected String realizeStockMove(StockMove stockMove, boolean checkOngoingInventoryFlag)
    throws AxelorException {
  if (stockMove.getStatusSelect() == null
      || stockMove.getStatusSelect() != StockMoveRepository.STATUS_PLANNED) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_INCONSISTENCY,
        I18n.get(StockExceptionMessage.STOCK_MOVE_REALIZATION_WRONG_STATUS));
  }

  LOG.debug("Stock realization : {} ", stockMove.getStockMoveSeq());

  if (stockMove.getTypeSelect() == StockMoveRepository.TYPE_INCOMING
      && !stockMove.getIsReversion()
      && appStockService.getAppStock().getIsRequiredShipmentSupplierDetails()
      && (stockMove.getSupplierShipmentDate() == null
          || Strings.isNullOrEmpty(stockMove.getSupplierShipmentRef()))) {
    throw new AxelorException(
        stockMove,
        TraceBackRepository.CATEGORY_MISSING_FIELD,
        I18n.get(StockExceptionMessage.STOCK_MOVE_MISSING_SUPPLIER_SHIPMENT_DETAILS));
  }

  if (checkOngoingInventoryFlag) {
    checkOngoingInventory(stockMove);
  }

  int initialStatus = stockMove.getStatusSelect();

  String newStockSeq = null;
  stockMoveLineService.checkTrackingNumber(stockMove);
  stockMoveLineService.checkConformitySelection(stockMove);
  fillRealizeWapPriceForStockMove(stockMove);

  stockMoveLineService.checkExpirationDates(stockMove);

  BigDecimal exTaxTotal = stockMoveToolService.compute(stockMove);
  stockMove = JpaModelHelper.ensureManaged(stockMove);
  setRealizedStatus(stockMove);
  stockMove.setRealDate(appBaseService.getTodayDate(stockMove.getCompany()));
  stockMove.setExTaxTotal(exTaxTotal);

  stockMove = stockMoveRepo.save(stockMove);

  stockMoveLineService.updateLocations(
      initialStatus,
      StockMoveRepository.STATUS_CANCELED,
      getPlannedStockMoveLineIds(stockMove, true),
      stockMove.getEstimatedDate(),
      false,
      false,
      true);

  stockMoveLineService.updateLocations(
      StockMoveRepository.STATUS_DRAFT,
      StockMoveRepository.STATUS_REALIZED,
      getStockMoveLineIds(stockMove),
      stockMove.getEstimatedDate(),
      true,
      true,
      true);

  stockMove = JpaModelHelper.ensureManaged(stockMove);
  clearPlannedStockMoveLine(stockMove, true);
  storeCustomsCodesForStockMove(stockMove);
  resetMasses(stockMove);

  boolean mustBeSplit = mustBeSplit(stockMove);
  if (stockMove.getIsWithBackorder() && mustBeSplit) {
    Optional<StockMove> newStockMove =
        copyAndSplitStockMove(JpaModelHelper.ensureManaged(stockMove));
    if (newStockMove.isPresent()) {
      newStockSeq = newStockMove.get().getStockMoveSeq();
    }
  }

  if (stockMove.getIsWithReturnSurplus() && mustBeSplit) {
    Optional<StockMove> newStockMove =
        copyAndSplitStockMoveReverse(JpaModelHelper.ensureManaged(stockMove), true);
    if (newStockMove.isPresent()) {
      if (newStockSeq != null) {
        newStockSeq = newStockSeq + " " + newStockMove.get().getStockMoveSeq();
      } else {
        newStockSeq = newStockMove.get().getStockMoveSeq();
      }
    }
  }
  computeMasses(stockMove);

  stockMove = stockMoveRepo.find(stockMove.getId());
  if (stockMove.getTypeSelect() == StockMoveRepository.TYPE_INCOMING
      && !stockMove.getIsReversion()) {
    partnerProductQualityRatingService.calculate(stockMove);
  }

  return newStockSeq;
}

@Override
@Transactional
public void copyQtyToRealQty(StockMove stockMove) {
  if (stockMove == null) {
    return;
  }

  if (stockMove.getId() != null) {
    Query<StockMoveLine> query = getStockMoveLineQuery(stockMove.getId());
    BatchProcessorHelper.of()
        .<StockMoveLine>forEachByQuery(
            query,
            line -> stockMoveLineService.fillRealQuantities(line, stockMove, line.getQty()));
  }
}

protected void updateLocationForStockMoveLine(
    StockMoveLine stockMoveLine,
    boolean realQty,
    int fromStatus,
    int toStatus,
    LocalDate lastFutureStockMoveDate,
    LocalDate date,
    String origin,
    boolean generateOrder,
    Set<Long> productIdsForWapUpdate)
    throws AxelorException {
  StockLocation fromStockLocation = stockMoveLine.getFromStockLocation();
  StockLocation toStockLocation = stockMoveLine.getToStockLocation();
  Product product = stockMoveLine.getProduct();
  if (product == null
      || !product.getProductTypeSelect().equals(ProductRepository.PRODUCT_TYPE_STORABLE)) {
    return;
  }

  BigDecimal qty;
  if (realQty) {
    qty = stockMoveLine.getRealQty();
  } else {
    qty = stockMoveLine.getQty();
  }

  this.updateLocations(
      stockMoveLine,
      product,
      qty,
      fromStatus,
      toStatus,
      lastFutureStockMoveDate,
      stockMoveLine.getTrackingNumber(),
      generateOrder);
  if (toStatus == StockMoveRepository.STATUS_REALIZED) {

    if (fromStockLocation.getTypeSelect() != StockLocationRepository.TYPE_VIRTUAL) {
      // We dont recompute average price for outgoing lines
      this.updateStockLocationLineHistory(
          fromStockLocation, stockMoveLine, date, origin, toStatus);
    }
    if (toStockLocation.getTypeSelect() != StockLocationRepository.TYPE_VIRTUAL) {
      this.updateAveragePriceAndLocationLineHistory(
          toStockLocation, stockMoveLine, fromStatus, toStatus, date, origin);
    }
    productIdsForWapUpdate.add(product.getId());
  }
  if (fromStatus == StockMoveRepository.STATUS_REALIZED
      && toStatus == StockMoveRepository.STATUS_CANCELED) {
    // We dont recompute on cancel
    if (fromStockLocation.getTypeSelect() != StockLocationRepository.TYPE_VIRTUAL) {
      this.updateStockLocationLineHistory(
          fromStockLocation, stockMoveLine, date, origin, toStatus);
    }
    if (toStockLocation.getTypeSelect() != StockLocationRepository.TYPE_VIRTUAL) {
      this.updateStockLocationLineHistory(toStockLocation, stockMoveLine, date, origin, toStatus);
    }
  }
}

protected void updateStockLocationLineHistory(
    StockLocation stockLocation,
    StockMoveLine stockMoveLine,
    LocalDate date,
    String origin,
    int toStatus)
    throws AxelorException {
  StockLocationLine stockLocationLine =
      stockLocationLineService.getOrCreateStockLocationLine(
          stockLocation, stockMoveLine.getProduct());
  if (stockLocationLine == null) {
    return;
  }

  if (origin == null) {
    origin =
        Optional.ofNullable(stockMoveLine)
            .map(StockMoveLine::getStockMove)
            .map(StockMove::getStockMoveSeq)
            .orElse("");
  }

  if (toStatus == StockMoveRepository.STATUS_CANCELED) {
    resetAvgPrice(stockLocationLine, origin);
  } else {
    setAvgPriceAndComputeForProduct(
        stockLocationLine,
        Optional.ofNullable(stockLocationLine.getAvgPrice()).orElse(BigDecimal.ZERO));
  }

  stockLocationLineService.updateHistory(
      stockLocationLine,
      stockMoveLine,
      date != null ? date.atStartOfDay() : null,
      origin,
      getStockLocationLineHistoryTypeSelect(toStatus));
}

@Override
public void updateAveragePriceAndLocationLineHistory(
    StockLocation stockLocation,
    StockMoveLine stockMoveLine,
    int fromStatus,
    int toStatus,
    LocalDate date,
    String origin)
    throws AxelorException {
  StockLocationLine stockLocationLine =
      stockLocationLineService.getOrCreateStockLocationLine(
          stockLocation, stockMoveLine.getProduct());
  if (stockLocationLine == null) {
    return;
  }

  if (toStatus == StockMoveRepository.STATUS_REALIZED) {
    BigDecimal avgPrice =
        this.computeNewAveragePriceLocationLine(stockLocationLine, stockMoveLine);
    setAvgPriceAndComputeForProduct(stockLocationLine, avgPrice);

    stockLocationLineService.updateHistory(
        stockLocationLine,
        stockMoveLine,
        date != null ? date.atStartOfDay() : null,
        origin,
        getStockLocationLineHistoryTypeSelect(toStatus));
  }
}

protected String getStockLocationLineHistoryTypeSelect(int statusStockMove) {
  switch (statusStockMove) {
    case StockMoveRepository.STATUS_CANCELED:
      return StockLocationLineHistoryRepository.TYPE_SELECT_CANCELATION;
    case StockMoveRepository.STATUS_REALIZED:
      return StockLocationLineHistoryRepository.TYPE_SELECT_STOCK_MOVE;
    default:
      return null;
  }
}

@Override
@Transactional(rollbackOn = {Exception.class})
public void updateLocation(
    StockLocation stockLocation,
    Product product,
    Unit stockMoveLineUnit,
    BigDecimal qty,
    boolean current,
    boolean future,
    boolean isIncrement,
    LocalDate lastFutureStockMoveDate,
    boolean generateOrder)
    throws AxelorException {

  StockLocationLine stockLocationLine = this.getOrCreateStockLocationLine(stockLocation, product);

  if (stockLocationLine == null) {
    return;
  }

  Unit stockLocationLineUnit = stockLocationLine.getUnit();
  if (stockLocationLineUnit == null) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_CONFIGURATION_ERROR,
        I18n.get(StockExceptionMessage.LOCATION_LINE_MISSING_UNIT),
        stockLocation.getName(),
        product.getFullName());
  }
  if (!stockLocationLineUnit.equals(stockMoveLineUnit)) {
    qty =
        unitConversionService.convert(
            stockMoveLineUnit, stockLocationLineUnit, qty, qty.scale(), product);
  }

  LOG.debug(
      "Stock update : Stock location? {}, Product? {}, Quantity? {}, Current quantity? {}, Future quantity? {}, Is increment? {}, Date? {} ",
      stockLocation.getName(),
      product.getCode(),
      qty,
      current,
      future,
      isIncrement,
      lastFutureStockMoveDate);

  if (generateOrder && isIncrement) {
    maxStockRules(product, qty, stockLocationLine, current, future);
  }

  stockLocationLine =
      this.updateLocation(
          stockLocationLine,
          stockMoveLineUnit,
          product,
          qty,
          current,
          future,
          isIncrement,
          lastFutureStockMoveDate);

  this.checkStockMin(stockLocationLine, false);

  stockLocationLineRepo.save(stockLocationLine);
}

@Override
public StockLocationLine updateLocation(
    StockLocationLine stockLocationLine,
    Unit stockMoveLineUnit,
    Product product,
    BigDecimal qty,
    boolean current,
    boolean future,
    boolean isIncrement,
    LocalDate lastFutureStockMoveDate)
    throws AxelorException {

  if (current) {
    if (isIncrement) {
      stockLocationLine.setCurrentQty(stockLocationLine.getCurrentQty().add(qty));
    } else {
      stockLocationLine.setCurrentQty(stockLocationLine.getCurrentQty().subtract(qty));
    }
  }
  if (future) {
    stockLocationLine.setFutureQty(computeFutureQty(stockLocationLine));
    stockLocationLine.setLastFutureStockMoveDate(lastFutureStockMoveDate);
  }

  return stockLocationLine;
}

@Override
@Transactional(rollbackOn = {Exception.class})
public void updateDetailLocation(
    StockLocation stockLocation,
    Product product,
    Unit stockMoveLineUnit,
    BigDecimal qty,
    boolean current,
    boolean future,
    boolean isIncrement,
    LocalDate lastFutureStockMoveDate,
    TrackingNumber trackingNumber)
    throws AxelorException {

  StockLocationLine detailLocationLine =
      this.getOrCreateDetailLocationLine(stockLocation, product, trackingNumber);

  if (detailLocationLine == null) {
    return;
  }

  Unit stockLocationLineUnit = detailLocationLine.getUnit();

  if (stockLocationLineUnit == null) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_CONFIGURATION_ERROR,
        I18n.get(StockExceptionMessage.DETAIL_LOCATION_LINE_MISSING_UNIT),
        trackingNumber.getTrackingNumberSeq(),
        stockLocation.getName(),
        product.getFullName());
  }
  if (!stockLocationLineUnit.equals(stockMoveLineUnit)) {
    qty =
        unitConversionService.convert(
            stockMoveLineUnit, stockLocationLineUnit, qty, qty.scale(), product);
  }

  LOG.debug(
      "Stock detail update : Stock location? {}, Product? {}, Quantity? {}, Current quantity? {}, Future quantity? {}, Is increment? {}, Date? {}, Tracking number? {} ",
      stockLocation.getName(),
      product.getCode(),
      qty,
      current,
      future,
      isIncrement,
      lastFutureStockMoveDate,
      trackingNumber);

  detailLocationLine =
      this.updateLocation(
          detailLocationLine,
          stockMoveLineUnit,
          product,
          qty,
          current,
          future,
          isIncrement,
          lastFutureStockMoveDate);

  this.checkStockMin(detailLocationLine, true);

  stockLocationLineRepo.save(detailLocationLine);
}

@Override
public void updateHistory(
    StockLocationLine stockLocationLine,
    StockMoveLine stockMoveLine,
    LocalDateTime dateT,
    String origin,
    String typeSelect)
    throws AxelorException {

  if (origin == null) {
    origin =
        Optional.ofNullable(stockMoveLine)
            .map(StockMoveLine::getStockMove)
            .map(StockMove::getStockMoveSeq)
            .orElse("");
  }

  if (dateT == null) {
    Company company = getCompany(stockLocationLine);
    dateT = appBaseService.getTodayDateTime(company).toLocalDateTime();
  }
  stockLocationLineHistoryService.saveHistory(stockLocationLine, dateT, origin, typeSelect);
}

@Override
public StockLocationLine getOrCreateStockLocationLine(
    StockLocation stockLocation, Product product) {

  if (!product.getStockManaged()) {
    return null;
  }

  StockLocationLine stockLocationLine =
      stockLocationLineFetchService.getStockLocationLine(stockLocation, product);

  if (stockLocationLine == null) {
    stockLocationLine = this.createLocationLine(stockLocation, product);
  }

  LOG.debug(
      "Get stock line: Stock location? {}, Product? {}, Current quantity? {}, Future quantity? {}, Date? {} ",
      stockLocationLine.getStockLocation().getName(),
      product.getCode(),
      stockLocationLine.getCurrentQty(),
      stockLocationLine.getFutureQty(),
      stockLocationLine.getLastFutureStockMoveDate());

  return stockLocationLine;
}

@Override
public StockLocationLine getOrCreateDetailLocationLine(
    StockLocation detailLocation, Product product, TrackingNumber trackingNumber) {

  StockLocationLine detailLocationLine =
      stockLocationLineFetchService.getDetailLocationLine(
          detailLocation, product, trackingNumber);

  if (detailLocationLine == null) {
    detailLocationLine = this.createDetailLocationLine(detailLocation, product, trackingNumber);
  }

  LOG.debug(
      "Get stock line detail: Stock location? {}, Product? {}, Current quantity? {}, Future quantity? {}, Date? {}, Num de suivi? {} ",
      detailLocationLine.getDetailsStockLocation().getName(),
      product.getCode(),
      detailLocationLine.getCurrentQty(),
      detailLocationLine.getFutureQty(),
      detailLocationLine.getLastFutureStockMoveDate(),
      detailLocationLine.getTrackingNumber());

  return detailLocationLine;
}

@Override
public StockLocationLine createLocationLine(StockLocation stockLocation, Product product) {

  LOG.debug(
      "Stock line creation : Stock location? {}, Product? {} ",
      stockLocation.getName(),
      product.getCode());

  StockLocationLine stockLocationLine = new StockLocationLine();

  stockLocationLine.setStockLocation(stockLocation);
  stockLocationLine.setProduct(product);
  stockLocationLine.setUnit(product.getUnit());
  stockLocationLine.setCurrentQty(BigDecimal.ZERO);
  stockLocationLine.setFutureQty(BigDecimal.ZERO);

  return stockLocationLine;
}

@Override
public StockLocationLine createDetailLocationLine(
    StockLocation stockLocation, Product product, TrackingNumber trackingNumber) {

  LOG.debug(
      "Stock line detail creation : Stock location? {}, Product? {}, Tracking number? {} ",
      stockLocation.getName(),
      product.getCode(),
      trackingNumber.getTrackingNumberSeq());

  StockLocationLine detailLocationLine = new StockLocationLine();

  detailLocationLine.setDetailsStockLocation(stockLocation);
  detailLocationLine.setProduct(product);
  detailLocationLine.setUnit(product.getUnit());
  detailLocationLine.setCurrentQty(BigDecimal.ZERO);
  detailLocationLine.setFutureQty(BigDecimal.ZERO);
  detailLocationLine.setTrackingNumber(trackingNumber);

  return detailLocationLine;
}

@Override
public BigDecimal convertToProductUnit(StockLocationLine stockLocationLine, BigDecimal value)
    throws AxelorException {
  Product product = stockLocationLine.getProduct();
  return convert(stockLocationLine.getUnit(), productUnit(product), value, product);
}

@Override
public BigDecimal convertFromProductUnit(StockLocationLine stockLocationLine, BigDecimal value)
    throws AxelorException {
  Product product = stockLocationLine.getProduct();
  return convert(productUnit(product), stockLocationLine.getUnit(), value, product);
}

protected Unit productUnit(Product product) {
  return product == null ? null : product.getUnit();
}

protected BigDecimal convert(Unit startUnit, Unit endUnit, BigDecimal value, Product product)
    throws AxelorException {
  if (value == null || startUnit == null || endUnit == null || startUnit.equals(endUnit)) {
    return value;
  }
  return unitConversionService.convertWithAutoFlushFalse(
      startUnit, endUnit, value, value.scale(), product);
}

